def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_def = 0
    opp_def = 0
    my_last = history[-1][0]
    opp_last = history[-1][1]
    for m, o in history:
        if m == 'D':
            my_def += 1
        if o == 'D':
            opp_def += 1

    opp_def_rate = opp_def / n

    recent_opp_def = 0
    for i in range(max(0, n - 10), n):
        if history[i][1] == 'D':
            recent_opp_def += 1

    if n >= 99:
        return 'D'
    if n == 98:
        retaliated = False
        for i in range(1, n):
            if history[i-1][0] == 'D' and history[i][1] == 'D':
                retaliated = True
                break
        if retaliated and opp_def_rate < 0.5:
            return 'C'
        else:
            return 'D'

    if opp_def_rate > 0.5 or recent_opp_def >= 6:
        return 'D'

    if n == 1 and my_def == 0 and opp_def == 0:
        return 'D'

    if opp_def == 0:
        if my_def == 0:
            return 'C'
        else:
            if my_last == 'D':
                if my_def == 1:
                    return 'C'
                else:
                    return 'D'
            else:
                if rng.random() < 0.8:
                    return 'D'
                return 'C'

    if opp_last == 'C':
        return 'C'
    else:
        if opp_def_rate > 0.4 or recent_opp_def >= 5:
            return 'D'
        if rng.random() < 0.6:
            return 'C'
        return 'D'
